"""
This module contains the tracking functionality for the artifacts.


The following class is available:

    * :class:`MLExperiments`
    * :func:`get_tracking_log_by_run`
    * :func:`get_tracking_log_header_by_run`
    * :func:`get_tracking_metadata_by_run`
    * :func:`get_tracking_log` (deprecated)
    * :func:`get_tracking_metadata` (deprecated)
    * :func:`delete_tracking_log_by_run`
    * :func:`delete_run_log`
    * :func:`delete_tracking_log` (deprecated)
    * :func:`delete_experiment_log`
"""
#pylint: disable=protected-access

import logging
import uuid
import warnings
from hdbcli import dbapi
from hana_ml.algorithms.pal.pal_base import PALBase, try_drop
from hana_ml.algorithms.pal.sqlgen import ParameterTable
from hana_ml.algorithms.pal.utility import check_pal_function_exist

logger = logging.getLogger(__name__)
class MLExperiments(object):
    """
    This class is used to track the models and datasets.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection to the SAP HANA system.
    experiment_id: str
        The experiment id for the model.
    experiment_description: str, optional
        The experiment description for the model.
    """
    EXPERIMENT_SPLITTER = "_<EXPERIMENT_SPLITTER>_"
    current_run_name = None
    count = 0

    def __init__(self,
                 connection_context,
                 experiment_id,
                 experiment_description=None):
        self.connection_context = connection_context
        self.experiment_id = experiment_id
        self.experiment_description = experiment_description
        self.count = 0

    def get_current_tracking_id(self):
        """
        This function is used to get the current tracking id.

        Returns
        -------
        str
            The current tracking id.
        """
        return self.experiment_id + self.EXPERIMENT_SPLITTER + self.current_run_name

    def autologging(
            self,
            model,
            run_name=None,
            dataset_name=None,
            dataset_source=None,
            track_id=None,
            track_description=None):
        """
        This function is used to track the PAL function call.

        Parameters
        ----------
        model: object
            The model object to be tracked.
        run_name: str, optional
            The name of the run. If not provided, it will be generated automatically.
        dataset_name: str, optional
            The name of the dataset used in the PAL function call.
        dataset_source: str, optional
            The source of the dataset used in the PAL function call.
        track_id: str, optional
            The tracking id for the run in the experiment.
        track_description: str, optional
            The tracking description for the run.

        Returns
        -------
        None
        """
        if track_id is not None:
            warnings.warn(
                "track_id is deprecated. Use experiment_id and run_name instead.",
                DeprecationWarning,
                stacklevel=2,
            )
        if run_name is None:
            run_name = "run_" + str(self.count)
            self.count += 1
        if track_id is None:
            track_id = self.experiment_id + self.EXPERIMENT_SPLITTER + run_name
        if track_description is None:
            track_description = self.experiment_description
        model._extend_pal_parameter({
            'LOG_ML_TRACK': 1,
            'TRACK_ID': track_id,
            'TRACK_DESCRIPTION': track_description,
            'DATASET_NAME': dataset_name,
            'DATASET_SOURCE': dataset_source
        })
        self.current_run_name = run_name

    def get_tracking_log_for_current_run(self):
        """
        This function is used to get the tracking log for the current run.

        Returns
        -------
        DataFrame
            The tracking log for the current run.
        """
        current_track_id = self.experiment_id + self.EXPERIMENT_SPLITTER + self.current_run_name
        return get_tracking_log(self.connection_context, current_track_id)

    def get_tracking_metadata_for_current_run(self):
        """
        This function is used to get the tracking metadata for the current run.

        Returns
        -------
        DataFrame
            The tracking metadata for the current run.
        """
        current_track_id = self.experiment_id + self.EXPERIMENT_SPLITTER + self.current_run_name
        return get_tracking_metadata(self.connection_context, current_track_id)

def get_tracking_log(connection_context, track_id):
    """
    This function is used to get the tracking log for the given track_id.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection context object to the SAP HANA system.
    track_id: str
        The tracking id for the model.
    """
    warnings.warn(
        "get_tracking_log is deprecated. Use get_tracking_log_by_run instead.",
        DeprecationWarning,
        stacklevel=2,
    )
    return connection_context.table(table="TRACK_LOG", schema="PAL_ML_TRACK").filter("EXECUTION_ID = '{}'".format(track_id))

def get_tracking_metadata(connection_context, track_id):
    """
    This function is used to get the tracking metadata for the given track_id.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection context object to the SAP HANA system.
    track_id: str
        The tracking id for the model.
    """
    warnings.warn(
        "get_tracking_metadata is deprecated. Use get_tracking_metadata_by_run instead.",
        DeprecationWarning,
        stacklevel=2,
    )
    return connection_context.table(table="TRACK_METADATA", schema="PAL_ML_TRACK").filter("TRACK_ID = '{}'".format(track_id))


def _escape_sql_value(value):
    if value is None:
        return None
    return str(value).replace("'", "''")


def _build_execution_id(experiment_id, run_id):
    if not experiment_id or not run_id:
        raise ValueError("experiment_id and run_id must be provided.")
    return experiment_id + MLExperiments.EXPERIMENT_SPLITTER + run_id


def _get_tracking_log_df_by_execution_id(connection_context, execution_id, event_key=None):
    escaped_execution_id = _escape_sql_value(execution_id)
    escaped_event_key = _escape_sql_value(event_key)

    where_clause = "EXECUTION_ID = '{}'".format(escaped_execution_id)
    if escaped_event_key is not None:
        where_clause += " AND EVENT_KEY = '{}'".format(escaped_event_key)

    query = """
        WITH merged AS (
            SELECT
                EXECUTION_ID,
                SEQ,
                EVENT_KEY,
                SUBSTRING(
                    STRING_AGG(EVENT_MESSAGE, '' ORDER BY EVENT_TIMESTAMP),
                    1,
                    5000
                ) AS EVENT_MESSAGE_MERGED
            FROM PAL_ML_TRACK.TRACK_LOG
            WHERE {where_clause}
            GROUP BY EXECUTION_ID, SEQ, EVENT_KEY
        ),
        base AS (
            SELECT
                TRACK_LOG.*,
                ROW_NUMBER() OVER (
                    PARTITION BY EXECUTION_ID, SEQ, EVENT_KEY
                    ORDER BY EVENT_TIMESTAMP
                ) AS RN
            FROM PAL_ML_TRACK.TRACK_LOG AS TRACK_LOG
            WHERE {where_clause}
        )
        SELECT
            base.*,
            merged.EVENT_MESSAGE_MERGED
        FROM base
        JOIN merged
            ON base.EXECUTION_ID = merged.EXECUTION_ID
            AND base.SEQ = merged.SEQ
            AND base.EVENT_KEY = merged.EVENT_KEY
        WHERE base.RN = 1
        ORDER BY base.EVENT_TIMESTAMP
    """.format(where_clause=where_clause)

    result = connection_context.sql(query)
    if "RN" in result.columns:
        result = result.drop(["RN"])
    if "EVENT_MESSAGE_MERGED" in result.columns:
        if "EVENT_MESSAGE" in result.columns:
            result = result.drop(["EVENT_MESSAGE"])
        result = result.rename_columns({"EVENT_MESSAGE_MERGED": "EVENT_MESSAGE"})
    return result


def get_tracking_log_by_run(connection_context, experiment_id, run_id, event_key=None):
    """
    This function returns the tracking log SAP HANA DataFrame for the given run.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection context object to the SAP HANA system.
    experiment_id: str
        The experiment id for the model.
    run_id: str
        The run id for the model.
    event_key: str, optional
        The event key used to filter the log.
    """
    execution_id = _build_execution_id(experiment_id, run_id)
    return _get_tracking_log_df_by_execution_id(connection_context, execution_id, event_key)


def get_tracking_log_header_by_run(connection_context, experiment_id, run_id, event_key=None):
    """
    This function returns the tracking log header SAP HANA DataFrame for the given run.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection context object to the SAP HANA system.
    experiment_id: str
        The experiment id for the model.
    run_id: str
        The run id for the model.
    event_key: str, optional
        The event key used to filter the log header.
    """
    execution_id = _build_execution_id(experiment_id, run_id)
    escaped_execution_id = _escape_sql_value(execution_id)
    escaped_event_key = _escape_sql_value(event_key)

    where_clause = "EXECUTION_ID = '{}'".format(escaped_execution_id)
    if escaped_event_key is not None:
        where_clause += " AND EVENT_KEY = '{}'".format(escaped_event_key)

    query = """
        SELECT *
        FROM PAL_ML_TRACK.TRACK_LOG_HEADER
        WHERE {where_clause}
    """.format(where_clause=where_clause)

    return connection_context.sql(query)


def get_tracking_metadata_by_run(connection_context, experiment_id, run_id):
    """
    This function returns the tracking metadata SAP HANA DataFrame for the given run.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection context object to the SAP HANA system.
    experiment_id: str
        The experiment id for the model.
    run_id: str
        The run id for the model.
    """
    execution_id = _build_execution_id(experiment_id, run_id)
    escaped_execution_id = _escape_sql_value(execution_id)
    query = """
        SELECT *
        FROM PAL_ML_TRACK.TRACK_METADATA
        WHERE TRACK_ID = '{}'
    """.format(escaped_execution_id)
    return connection_context.sql(query)

def delete_run_log(connection_context, experiment_id, run_name, remove_mode=False, is_force=False):
    """
    This function is used to delete the tracking log for the given run_name.

    Parameters
    ----------
    connection: object
        The connection object.
    experiment_id: str
        The experiment id for the model.
    run_name: str
        The run name for the model.
    """
    track_id = experiment_id + MLExperiments.EXPERIMENT_SPLITTER + run_name
    _delete_tracking_log(connection_context, track_id, remove_mode, is_force)


def delete_tracking_log_by_run(connection_context, experiment_id, run_name, remove_mode=False, is_force=False):
    """
    This function is used to delete the tracking log for the given run_name.

    Parameters
    ----------
    connection: object
        The connection object.
    experiment_id: str
        The experiment id for the model.
    run_name: str
        The run name for the model.
    """
    delete_run_log(connection_context, experiment_id, run_name, remove_mode, is_force)


def delete_tracking_log(connection_context, track_id, remove_mode=False, is_force=False):
    """
    This function is used to delete the tracking log for the given track_id.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection context object to the SAP HANA system.
    track_id: str
        The tracking id for the model.
    """
    warnings.warn(
        "delete_tracking_log is deprecated. Use delete_tracking_log_by_run instead.",
        DeprecationWarning,
        stacklevel=2,
    )
    _delete_tracking_log(connection_context, track_id, remove_mode, is_force)

def _delete_tracking_log(connection_context, track_id, remove_mode=False, is_force=False):
    """
    This function is used to delete the tracking log for the given track_id.

    Parameters
    ----------
    connection_context : :class:`~hana_ml.dataframe.ConnectionContext`
        The connection context object to the SAP HANA system.
    track_id: str
        The tracking id for the model.
    """
    # connection_context.execute_sql("""
    #                             DELETE FROM "PAL_ML_TRACK"."TRACK_LOG" WHERE EXECUTION_ID = '{0}';
    #                             DELETE FROM "PAL_ML_TRACK"."TRACK_LOG_HEADER" WHERE EXECUTION_ID = '{0}';
    #                             DELETE FROM "PAL_ML_TRACK"."TRACK_METADATA" WHERE TRACK_ID = '{0}';
    #                             """.format(track_id))
    unique_id = str(uuid.uuid1()).replace('-', '_').upper()
    output = '#PAL_REMOVE_TRACK_INFO' + unique_id
    param_rows = [('REMOVE_MODE', remove_mode, None, None),
                  ('TRACK_ID', None, None, track_id),
                  ('IS_FORCE', is_force, None, None)]
    try:
        if check_pal_function_exist(connection_context, '%REMOVE_MLTRACK_LOG%', like=True):
            if not connection_context.has_table(output):
                PALBase()._call_pal_auto(connection_context,
                                        'PAL_REMOVE_MLTRACK_LOG',
                                        ParameterTable().with_data(param_rows),
                                        output)
        else:
            return False
    except dbapi.Error as db_err:
        logger.error(str(db_err))
        try_drop(connection_context, output)
    except Exception as db_err:
        logger.error(str(db_err))
        try_drop(connection_context, output)

def delete_experiment_log(connection_context, experiment_id, remove_mode=False, is_force=False):
    """
    This function is used to delete the tracking log for the given experiment_id.

    Parameters
    ----------
    connection: object
        The connection object.
    experiment_id: str
        The experiment id for the model.
    """
    track_ids = connection_context.sql("SELECT EXECUTION_ID FROM PAL_ML_TRACK.TRACK_LOG").filter("EXECUTION_ID LIKE '{}%'".format(experiment_id)).distinct().collect()["EXECUTION_ID"].tolist()
    for track_id in track_ids:
        _delete_tracking_log(connection_context, track_id, remove_mode, is_force)
